export function dashboardView({bank,history,name,covered,best,title,btn,icon,esc,grade,modeLabel,date,packageCard,topicCard}){
 const cov=covered(),pct=bank.length?Math.round(cov/bank.length*100):0;
 const pckTopics=['Algoritma & pemrograman','Pembelajaran Informatika','Literasi digital','Analisis data','Berpikir komputasional','Sistem & jaringan'];
 const today=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'});
 return `<div class="dashboard-page">${title('Langkah kecil, kesiapan besar.',`Selamat datang, ${esc(name)}! Persiapkan UKPPPG Informatika dengan latihan yang lebih terarah.`,`<span class="date-note">${icon('calendar')} ${today}</span>`)}
 <div class="dashboard-lead"><section class="hero editorial-hero"><div class="hero-copy"><h2>Bukan sekadar menjawab.<br><span>Belajar memahami.</span></h2><p>Latih logika, asah pedagogi, dan kenali potensimu.<br>Persiapan menjadi guru hebat dimulai dari sini.</p><div class="hero-actions">${btn('Pilih mode tryout','start-full','lime','arrow')}<span class="hero-foot">${icon('check')}Gratis, tanpa batas percobaan</span></div></div><span class="hero-code" aria-hidden="true">&lt;/&gt;</span><span class="hero-kicker">PPG CALON GURU · INFORMATIKA</span></section>
 <section class="card coverage-card" aria-label="Cakupan latihan"><div class="coverage-heading"><h2>Cakupan latihan</h2>${icon('chart')}</div><div class="coverage-value"><strong>${pct}<span>%</span></strong><p>bank soal dicoba</p></div><p class="coverage-mobile-count">${cov} dari ${bank.length} soal dicoba</p><div class="coverage-track" role="progressbar" aria-label="Bank soal yang sudah dicoba" aria-valuemin="0" aria-valuemax="${bank.length}" aria-valuenow="${cov}"><i style="width:${pct}%"></i></div><div class="coverage-legend"><span><i></i>Sudah dijawab <b>${cov} soal</b></span><span><i></i>Belum <b>${Math.max(0,bank.length-cov)}</b></span></div><p class="coverage-tip">${cov?'Lanjutkan eksplorasi topik untuk memperluas latihanmu.':'Mulai satu latihan untuk mengenali kemampuan dan memperluas cakupan belajarmu.'}</p></section></div>
 <section class="stats editorial-stats" aria-label="Statistik latihan">${[
 ['book',String(bank.length),'Soal siap dipelajari'],['target',String(history.length),'Sesi diselesaikan'],['sun',best()===null?'—':String(best()),'Skor latihan terbaik'],['clock',String(Math.round(history.reduce((s,h)=>s+h.elapsed,0)/60)),'Menit berlatih']
 ].map(([i,value,label])=>`<div class="stat"><strong class="stat-value">${value}</strong><span class="stat-label">${label}</span>${icon(i)}</div>`).join('')}</section>
 <div class="dashboard-middle"><section class="dashboard-packages"><div class="section-heading"><div><h2>Siap menguji kemampuan?</h2><p>Pilih langkah yang sesuai dengan waktumu hari ini.</p></div><a href="#tryout" class="text-link">Lihat semua ${icon('arrow')}</a></div>${packageCard()}<article class="card mini-package"><span class="icon-box gold">${icon('sun')}</span><div><h3>Punya waktu sebentar?</h3><p>Latihan cepat · 20 soal campuran · 35 menit</p></div>${btn('Coba sprint','start-sprint','','arrow')}</article></section>
 <section class="card recent editorial-recent"><div class="section-heading"><h2>Aktivitas belajarmu</h2><a href="#riwayat" class="text-link">Lihat riwayat ${icon('arrow')}</a></div>${history.length?history.slice(0,3).map(h=>{const g=grade(h.questions,h.answers);return `<article class="activity-row"><strong class="activity-score ${g.score>=70?'high':g.score>=60?'mid':'low'}">${g.score}</strong><div class="activity-info"><h3>${esc(h.title)}</h3><p>${date(h.finishedAt)} · ${g.correct}/${g.total} benar · ${modeLabel(h)}</p></div><button type="button" class="activity-open" data-action="result" data-id="${h.id}" aria-label="Lihat hasil ${esc(h.title)}">${icon('arrow')}</button></article>`;}).join(''):`<div class="empty activity-empty">${icon('history')}<h3>Perjalananmu dimulai di sini</h3><p>Selesaikan latihan pertama untuk melihat hasil dan perkembanganmu.</p><a class="text-link" href="#latihan">Mulai dari satu topik ${icon('arrow')}</a></div>`}<p class="activity-note">Skor latihan, bukan nilai resmi UKPPPG.</p></section></div>
 <section class="topic-section editorial-topics"><div class="section-heading"><div><h2>Fokus satu topik dulu</h2><p>Pahami konsepnya, lalu tingkatkan kepercayaan dirimu.</p></div></div><div class="topic-grid">${pckTopics.filter(t=>bank.some(q=>q.topic===t)).map(topicCard).join('')}</div></section>
 <div class="dashboard-bottom"><section class="card pu-dashboard editorial-pu"><div><span class="eyebrow">PEDAGOGI UMUM</span><h2>Bekal guru, lintas<br>bidang studi.</h2><p>Pelajari 8 ringkasan, berlatih per topik, dan kerjakan tryout khusus 30 soal.</p></div><div class="pu-quick"><div class="pu-quick-facts"><span><strong>8</strong>ringkasan</span><span><strong>30</strong>soal tryout</span></div><a class="btn lime" href="#pedagogi">Buka Pedagogi Umum ${icon('arrow')}</a></div></section>
 <section class="card readiness editorial-readiness"><div class="readiness-label"><span class="icon-box">${icon('bulb')}</span><span class="eyebrow">CATATAN PERSIAPAN</span></div><h2>Lebih dari ujian tertulis</h2><p>Siapkan juga studi kasus, perangkat pembelajaran, video praktik, dan wawancara reflektif.</p><a href="#referensi" class="text-link">Lihat bekal UKin ${icon('arrow')}</a></section></div></div>`;
}
